{"content": "/* coletar_stories_periodo.js — coleta COMPLETA de stories arquivados de um mês.
 *
 * USO (console do app Electron, página instagram.com já logada):
 *
 *   // 1) cole este arquivo inteiro no console
 *   // 2) rode:
 *   await __IG.periodo('2026-09')
 *   // 3) baixe os três arquivos:
 *   __IG.baixar('day_shells_2026-09.json', __IG.saida.day_shells)
 *   __IG.baixar('midias_2026-09.json',     __IG.saida.midias)
 *   __IG.baixar('insights_2026-09.json',   __IG.saida.insights)
 *
 * Depois, no disco:  python scripts/verificar_completude.py --periodo 2026-09 --dir <pasta>
 *
 * POR QUE ASSIM (e não varrendo a grade por DOM):
 *  - A grade /archive/stories/ é uma lista virtualizada: só existe no DOM o que está na
 *    janela visível. Uma varredura "completa" devolveu 184 dos 272 stories do mês.
 *  - day_shells devolve TODOS os dias do arquivo com media_count oficial -> é a fonte
 *    de contagem.
 *  - reels_media por dia devolve as mídias daquele dia -> é o inventário.
 *  - BaseSurface por mídia devolve as métricas -> é o conteúdo.
 * Três fontes independentes; o verificador cruza as três e falha se discordarem.
 *
 * ARMADILHAS JÁ PAGAS (não repita):
 *  - O `timestamp` do day_shells é o INÍCIO DO DIA em UTC (ex.: ...T00:01:40Z), não o
 *    taken_at. Subtrair o offset de BRT e ler campos UTC joga todo bucket um dia para
 *    trás: foi assim que 272 virou "270". Rotule pelo dia UTC e confira a borda do mês.
 *  - O `id` do bucket já vem com o prefixo: "archiveDay:123...". NÃO envolva de novo.
 *    `reel_ids:["archiveDay:archiveDay:123"]` devolve {"reels":{}} com status 200 —
 *    falha silenciosa.
 *  - A rota /api/graphql aceita UM media_id por chamada em BaseSurface (lote devolve
 *    variable_value_out_of_range).
 *  - O corpo do GraphQL é reconstruído dos tokens da própria página (dtsg/lsd/csrftoken).
 *    Nunca imprima esses valores; eles nunca devem sair do navegador.
 */
(() => {
  const EPOCH_MS = 1314220021721;
  const IGA = '936619743392459';
  const DOC_BASESURFACE = '28402237849463387'; // PolarisMediaInsightsBaseSurfaceQuery
  const FUSO_BRT = -3;

  const diaUTC = (ts) => new Date(ts * 1000).toISOString().slice(0, 10);
  const diaBRT = (ts) => new Date((ts - 10800) * 1000).toISOString().slice(0, 10);
  const jsonDe = (txt) => JSON.parse(String(txt).replace(/^for \(;;\);/, ''));
  const dormir = (ms) => new Promise((r) => setTimeout(r, ms));

  const auth = () => {
    const html = document.documentElement.innerHTML;
    const csrf = (document.cookie.split('; ').find((c) => c.startsWith('csrftoken=')) || '').split('=')[1] || '';
    const dtsg = (html.match(/"DTSGInitialData",\[\],\{"token":"([^"]+)"/) || html.match(/"fb_dtsg":"([^"]+)"/) || [])[1];
    const lsd = (html.match(/"LSD",\[\],\{"token":"([^"]+)"/) || html.match(/"lsd":"([^"]+)"/) || [])[1];
    if (!csrf || !dtsg || !lsd) throw new Error('tokens nao encontrados — recarregue a pagina logada');
    return { csrf, dtsg, lsd, jazoest: '2' + String(dtsg).split('').reduce((a, c) => a + c.charCodeAt(0), 0) };
  };

  const camada1 = async () => {
    const url = '/api/v1/archive/reel/day_shells/?timezone_offset=-10800&__d=www&__user=0&__a=1&__req=q&dpr=1';
    const r = await fetch(url, { credentials: 'include', headers: { 'x-ig-app-id': IGA } });
    const j = jsonDe(await r.text());
    const p = j.payload || j;
    const itens = p.items || [];
    return {
      total_dias_no_arquivo: itens.length,
      mais_available: p.more_available,
      buckets: itens.map((i) => ({
        dia_utc: i.timestamp ? diaUTC(i.timestamp) : null,
        id: i.id,
        media_count: i.media_count,
        latest_reel_media: i.latest_reel_media || null,
      })),
    };
  };

  const midiasDoBucket = async (bucket) => {
    const A = auth();
    // o id já vem como "archiveDay:..." — passar como está
    const r = await fetch('/api/v1/feed/reels_media/', {
      method: 'POST', credentials: 'include',
      headers: { 'content-type': 'application/x-www-form-urlencoded', 'x-csrftoken': A.csrf, 'x-ig-app-id': IGA },
      body: 'reel_ids=' + encodeURIComponent(JSON.stringify([bucket.id])) + '&__a=1&__d=www&__user=0',
    });
    const j = jsonDe(await r.text());
    const reel = (j.reels || {})[bucket.id];
    const itens = (reel && reel.items) || j.reels_media || [];
    return itens.map((m) => ({
      pk: String(m.pk),
      taken_at: m.taken_at,
      data_utc: diaUTC(m.taken_at),
      data_brt: diaBRT(m.taken_at),
      tipo: m.media_type,
      views: m.viewer_count,
      img: (m.image_versions2 && m.image_versions2.candidates && m.image_versions2.candidates[0] && m.image_versions2.candidates[0].url) || null,
      vid: (m.video_versions && m.video_versions[0] && m.video_versions[0].url) || null,
      w: m.original_width, h: m.original_height,
    }));
  };

  const insightsDaMidia = async (mediaId) => {
    const A = auth();
    const v = JSON.stringify({ query_params: { id: String(mediaId) }, is_creator_viewing_insights: true });
    const corpo = [
      'av=0', '__d=www', '__user=0', '__a=1', '__req=' + Math.random().toString(36).slice(2, 8),
      'dpr=1', '__ccg=EXCELLENT', '__rev=1049118338', '__comet_req=7',
      'fb_dtsg=' + encodeURIComponent(A.dtsg), 'jazoest=' + A.jazoest, 'lsd=' + encodeURIComponent(A.lsd),
      '__spin_r=1049118338', '__spin_b=trunk', '__spin_t=' + Math.floor(Date.now() / 1000),
      'fb_api_caller_class=RelayModern', 'fb_api_req_friendly_name=PolarisMediaInsightsBaseSurfaceQuery',
      'server_timestamps=true', 'variables=' + encodeURIComponent(v), 'doc_id=' + DOC_BASESURFACE,
    ].join('&');
    const r = await fetch('/api/graphql', {
      method: 'POST', credentials: 'include',
      headers: {
        'content-type': 'application/x-www-form-urlencoded', 'x-csrftoken': A.csrf, 'x-fb-lsd': A.lsd,
        'x-ig-app-id': IGA, 'x-asbd-id': '129477', 'x-fb-friendly-name': 'PolarisMediaInsightsBaseSurfaceQuery',
      },
      body: corpo,
    });
    const txt = await r.text();
    const j = jsonDe(txt);
    const media = j.data && j.data.media;
    if (!media) throw new Error('sem dados: ' + txt.slice(0, 160));
    const u = {};
    for (const [k, val] of Object.entries(media)) {
      if (val && typeof val === 'object' && 'value' in val) u[k] = val.value;
    }
    return { media_id: String(mediaId), reel_id: media.id || null, u };
  };

  window.__IG = {
    saida: null,
    auth,

    async periodo(periodo, opcoes = {}) {
      const atraso = opcoes.atraso || 200;
      const log = opcoes.log || (() => {});
      const ds = await camada1();
      const buckets = ds.buckets.filter((b) => b.dia_utc && b.dia_utc.slice(0, 7) === periodo);
      if (!buckets.length) throw new Error('nenhum bucket em ' + periodo + ' — confira o periodo');
      log(`day_shells: ${ds.total_dias_no_arquivo} dias no arquivo | ${buckets.length} dias em ${periodo} | esperado ${buckets.reduce((a, b) => a + b.media_count, 0)} stories`);

      const por_dia = {};
      const midias = [];
      for (const b of buckets) {
        const lista = await midiasDoBucket(b);
        if (lista.length !== b.media_count) {
          log(`AVISO ${b.dia_utc}: media_count=${b.media_count} mas reels_media devolveu ${lista.length}`);
        }
        por_dia[b.dia_utc] = lista;
        midias.push(...lista);
        await dormir(atraso);
      }
      log(`inventario: ${midias.length} midias (${new Set(midias.map((m) => m.pk)).size} unicas)`);

      const insights = {};
      let n = 0, falhas = 0;
      for (const m of midias) {
        try {
          insights[m.pk] = await insightsDaMidia(m.pk);
        } catch (e) {
          falhas++;
          insights[m.pk] = { media_id: m.pk, erro: String(e).slice(0, 200) };
        }
        n++;
        if (n % 25 === 0) log(`insights ${n}/${midias.length} (falhas: ${falhas})`);
        await dormir(atraso);
      }
      log(`insights: ${midias.length - falhas}/${midias.length} ok`);

      const comBorda = {};
      for (const b of ds.buckets) {
        if (b.dia_utc && b.dia_utc.slice(0, 7) !== periodo) comBorda[b.dia_utc] = b.media_count;
      }

      this.saida = {
        day_shells: {
          periodo, gerado_em: new Date().toISOString(),
          endpoint: 'GET /api/v1/archive/reel/day_shells/',
          total_dias_no_arquivo: ds.total_dias_no_arquivo,
          buckets, buckets_fora_do_periodo: comBorda,
          soma_media_count: buckets.reduce((a, b) => a + b.media_count, 0),
        },
        midias: {
          periodo, gerado_em: new Date().toISOString(),
          fonte: 'POST /api/v1/feed/reels_media/ (1 chamada por bucket)',
          convencao_data: 'data_utc = dia do bucket (UTC) | data_brt = taken_at - 3h',
          total: midias.length, por_dia,
        },
        insights: { periodo, gerado_em: new Date().toISOString(), fonte: 'PolarisMediaInsightsBaseSurfaceQuery', por_midia: insights },
      };
      return this.saida;
    },

    baixar(nome, obj) {
      const b = new Blob([JSON.stringify(obj, null, 1)], { type: 'application/json' });
      const a = document.createElement('a');
      a.href = URL.createObjectURL(b);
      a.download = nome;
      document.body.appendChild(a);
      a.click();
      a.remove();
      return nome + ' (' + b.size + ' bytes)';
    },
  };
  console.log('__IG pronto. Rode: await __IG.periodo("AAAA-MM")');
})();
