{"content": "#!/usr/bin/env python3
"""Sink de recebimento para payloads do navegador (contorna o dialogo de download).

Por que existe: no app Electron o download de blob abre um dialogo nativo de "Salvar"
que o agente nao consegue clicar. Navegar para http://127.0.0.1:<porta>/salvar?... NAO
e bloqueado pelo CSP do Instagram (o CSP restringe fetch/connect-src, nao a navegacao
de topo), entao o proprio navegador entrega o arquivo aqui.

Uso:
    python sink_save.py 8766 <pasta-de-destino>
    -> no console da pagina:
       location.href = 'http://127.0.0.1:8766/salvar?nome=insights_lote2.json&d=' + encodeURIComponent(__B64)

O payload 'd' pode ser base64 puro (JSON cru) ou base64 de gzip -- detectado pelo magic.
"""
import base64
import gzip
import hashlib
import json
import os
import sys
import urllib.parse
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer

DESTINO = os.path.abspath(sys.argv[2] if len(sys.argv) > 2 else ".")


class Handler(BaseHTTPRequestHandler):
    protocol_version = "HTTP/1.1"
    max_line = 4 * 1024 * 1024  # payload grande vem na query string

    def log_message(self, fmt, *a):  # silencio
        pass

    def _responder(self, code, obj):
        corpo = json.dumps(obj, ensure_ascii=False).encode("utf-8")
        self.send_response(code)
        self.send_header("Content-Type", "application/json; charset=utf-8")
        self.send_header("Content-Length", str(len(corpo)))
        self.end_headers()
        self.wfile.write(corpo)

    def do_GET(self):
        u = urllib.parse.urlparse(self.path)
        q = urllib.parse.parse_qs(u.query, max_num_fields=10)

        if u.path == "/health":
            return self._responder(200, {"ok": True, "destino": DESTINO, "ping": "ping-ok"})

        if u.path != "/salvar":
            return self._responder(404, {"erro": "rota desconhecida", "rotas": ["/health", "/salvar"]})

        nome = (q.get("nome") or [""])[0]
        dado = (q.get("d") or [""])[0]
        if not nome or not dado:
            return self._responder(400, {"erro": "informe nome= e d="})

        nome = os.path.basename(nome)  # nunca escrever fora do destino
        try:
            bruto = base64.b64decode(dado, validate=False)
        except Exception as e:
            return self._responder(400, {"erro": f"base64 invalido: {e}"})

        gzipado = bruto[:2] == b"\x1f\x8b"
        if gzipado:
            try:
                bruto = gzip.decompress(bruto)
            except Exception as e:
                return self._responder(400, {"erro": f"gzip corrompido: {e}"})

        if nome.endswith(".json"):
            try:
                json.loads(bruto.decode("utf-8"))
            except Exception as e:
                return self._responder(400, {"erro": f"json invalido: {e}"})

        os.makedirs(DESTINO, exist_ok=True)
        caminho = os.path.join(DESTINO, nome)
        with open(caminho, "wb") as fh:
            fh.write(bruto)

        return self._responder(200, {
            "ok": True, "arquivo": caminho, "bytes": len(bruto),
            "gzip_entrada": gzipado,
            "sha256": hashlib.sha256(bruto).hexdigest(),
        })


if __name__ == "__main__":
    porta = int(sys.argv[1]) if len(sys.argv) > 1 else 8766
    print(f"sink em http://127.0.0.1:{porta} -> {DESTINO}", flush=True)
    ThreadingHTTPServer(("127.0.0.1", porta), Handler).serve_forever()
