{"content": "#!/usr/bin/env python3
"""Normalizacao das metricas de story do BaseSurface — fonte unica de verdade.

POR QUE ESTE MODULO EXISTE
--------------------------
A mesma metrica chega em DOIS formatos, dependendo de qual superficie do
Instagram respondeu a `PolarisMediaInsightsBaseSurfaceQuery`:

  (a) lista simples   {"unified_total_content_views_count": [{"total_value": 428}]}
  (b) prefixo umapi_  {"umapi_unified_total_content_views_count": {"results": [{"total_value": 322}]}}

Numa rodada real de setembro/2026 os dois formatos vieram MISTURADOS no mesmo
arquivo: 121 registros no formato (a) e 152 no formato (b). Quem le so um dos
formatos conclui, errado, que metade dos dados esta vazia. Quem testa presenca
com `if registro["u"]` tambem erra: o formato (b) e truthy mesmo com
`{"results": []}`, ou seja, aceita captura oca como sucesso.

REGRA: toda leitura de metrica passa por `resultados()` / `totais_de()` /
`valor_de()`. Nunca acesse `registro["u"]["alguma_chave"]` direto.
"""

from __future__ import annotations

# --------------------------------------------------------------------- formato

PREFIXO_UMAPI = "umapi_"
CAMPOS_DE_CONTROLE = {"media_id", "reel_id", "tags", "status", "erro", "erros", "error"}


def corpo_de(registro):
    """O dicionario de metricas de um registro, seja qual for o empacotamento."""
    if not isinstance(registro, dict):
        return {}
    for chave in ("u", "metricas", "metrics", "dados"):
        valor = registro.get(chave)
        if isinstance(valor, dict):
            return valor
    return registro


def normalizar_nome(chave):
    """Remove o prefixo umapi_ para tratar os dois formatos como a mesma metrica."""
    return chave[len(PREFIXO_UMAPI):] if chave.startswith(PREFIXO_UMAPI) else chave


def resultados(metrica):
    """Devolve SEMPRE uma lista de itens {total_value, dimension_values?}.

    Aceita os dois formatos. Lista vazia quando nao houver nada — inclusive no
    caso perigoso `{"results": []}`, que e truthy mas nao tem dado nenhum.
    """
    if isinstance(metrica, list):
        return metrica
    if isinstance(metrica, dict):
        filho = metrica.get("results")
        if isinstance(filho, list):
            return filho
    return []


# -------------------------------------------------------------------- leitura

def totais_de(registro):
    """{nome_normalizado: maior total_value} de tudo que tiver numero.

    Usado para validar presenca de metrica: dicionario vazio == captura oca.
    """
    totais = {}
    for chave, bruto in corpo_de(registro).items():
        if chave in CAMPOS_DE_CONTROLE:
            continue
        nome = normalizar_nome(chave)
        itens = resultados(bruto)
        if itens:
            for item in itens:
                if isinstance(item, dict) and isinstance(item.get("total_value"), (int, float)):
                    totais[nome] = max(totais.get(nome, 0), int(item["total_value"]))
        elif isinstance(bruto, (int, float)) and not isinstance(bruto, bool):
            totais[nome] = int(bruto)
    return totais


def valor_de(registro, *nomes):
    """Primeiro total_value encontrado entre os nomes dados (ordem = prioridade).

    Cada nome e procurado nos dois formatos. `valor_de(r, "unified_total_content_views_count")`
    acha tanto a chave direta quanto a `umapi_`.
    """
    corpo = corpo_de(registro)
    for nome in nomes:
        for chave in (nome, PREFIXO_UMAPI + nome):
            itens = resultados(corpo.get(chave))
            for item in itens:
                if isinstance(item, dict) and isinstance(item.get("total_value"), (int, float)):
                    return int(item["total_value"])
    return None


def quebra_de(registro, nome):
    """{dimension_value: total_value} de uma metrica com breakdown (ex.: seguidor/nao seguidor)."""
    corpo = corpo_de(registro)
    for chave in (nome, PREFIXO_UMAPI + nome):
        itens = resultados(corpo.get(chave))
        if itens:
            saida = {}
            for item in itens:
                if not isinstance(item, dict):
                    continue
                dims = item.get("dimension_values") or []
                rotulo = str(dims[0]) if dims else "total"
                saida[rotulo] = int(item.get("total_value") or 0)
            return saida
    return {}


def tem_conteudo(registro):
    """True so quando ha pelo menos UMA metrica com numero de verdade.

    Presenca de chave NAO serve como prova: ja houve resposta 200 com todas as
    chaves presentes e vazias. Este e o teste que decide se uma captura vale.
    """
    if not isinstance(registro, dict):
        return False
    if registro.get("erro") or registro.get("erros") or registro.get("error"):
        return False
    return bool(totais_de(registro))


def formato_de(registro):
    """'umapi' | 'lista' | 'misto' | 'vazio' — para relatar a proveniencia da rodada."""
    nomes = [c for c in corpo_de(registro) if c not in CAMPOS_DE_CONTROLE]
    if not nomes:
        return "vazio"
    tem_umapi = any(n.startswith(PREFIXO_UMAPI) for n in nomes)
    tem_lista = any(not n.startswith(PREFIXO_UMAPI) for n in nomes)
    if tem_umapi and tem_lista:
        return "misto"
    if tem_umapi:
        return "umapi"
    if not totais_de(registro):
        return "vazio"
    return "lista"


# ------------------------------------------------------- mapa canonico -> CSV

# nome normalizado -> (coluna no CSV, rotulo em pt-BR)
MAPA = {
    "unified_total_content_views_count": ("visualizacoes", "Visualizações"),
    "content_meta_viewers_count": ("visualizadores", "Visualizadores"),
    "media_organic_account_reach_or_promoted_people_based_reach": ("alcance", "Alcance"),
    "foa_people_based_reach": ("alcance_organico", "Alcance orgânico"),
    "total_interactions_count": ("interacoes", "Interações"),
    "engaged_accounts": ("contas_com_engajamento", "Contas com engajamento"),
    "likes_count": ("curtidas", "Curtidas"),
    "comments_count": ("comentarios", "Comentários"),
    "saves_count": ("salvamentos", "Salvamentos"),
    "reshares_count": ("compartilhamentos", "Compartilhamentos"),
    "story_likes_count": ("curtidas_story", "Curtidas no story"),
    "story_replies_count_total": ("respostas", "Respostas"),
    "story_link_clicks_count": ("cliques_link", "Cliques no link"),
    "profile_views_from_impressions_count": ("visitas_perfil", "Visitas ao perfil"),
    "follows_from_impressions_count": ("novos_seguidores", "Novos seguidores"),
    "ig_posts_ccp_fb_views_count": ("views_fb_crosspost", "Views no Facebook (crosspost)"),
}

# metricas que so fazem sentido como quebra (dimension_values)
QUEBRAS = {
    "content_views_count_follow_type_breakdowns": ("views_seguidores", "views_nao_seguidores",
                                                   "Visualizações: 1=seguidor, 2=não seguidor"),
    "story_navigations_count_story_navigation_action_type_breakdowns": (
        None, "navegacoes", "Navegações (códigos de ação não mapeados)"),
}

# Colunas do CSV, na ordem. `None` = preenchida por outra fonte (visao, arquivo).
COLUNAS_CSV = [
    ("periodo_fonte", None),
    ("data_story", None),
    ("hora_story", None),
    ("media_id", None),
    ("tipo_midia", None),
    ("visualizacoes", "unified_total_content_views_count"),
    ("visualizadores", "content_meta_viewers_count"),
    ("alcance", "media_organic_account_reach_or_promoted_people_based_reach"),
    ("views_seguidores", "content_views_count_follow_type_breakdowns|1"),
    ("views_nao_seguidores", "content_views_count_follow_type_breakdowns|2"),
    ("interacoes", "total_interactions_count"),
    ("contas_com_engajamento", "engaged_accounts"),
    ("curtidas_story", "story_likes_count"),
    ("respostas", "story_replies_count_total"),
    ("compartilhamentos", "reshares_count"),
    ("salvamentos", "saves_count"),
    ("cliques_link", "story_link_clicks_count"),
    ("visitas_perfil", "profile_views_from_impressions_count"),
    ("novos_seguidores", "follows_from_impressions_count"),
    ("navegacoes", "story_navigations_count_story_navigation_action_type_breakdowns"),
    ("navegacoes_quebra", "story_navigations_count_story_navigation_action_type_breakdowns|bruto"),
    ("descricao_visao", None),
    ("texto_sobreposto", None),
    ("natureza", None),
    ("metricas_ausentes", None),
    ("formato_metricas", None),
    ("status_validacao", None),
    ("proveniencia", None),
]


def valor_coluna(registro, referencia):
    """Resolve uma referencia do COLUNAS_CSV para o valor daquele registro.

    Referencias aceitas:
      "chave"            -> total_value (nos dois formatos)
      "chave|1"          -> total_value do item cujo dimension_values[0] == "1"
      "chave|bruto"      -> a quebra inteira como JSON compacto
    """
    if not referencia:
        return None
    if "|" not in referencia:
        v = valor_de(registro, referencia)
        return "" if v is None else v
    chave, sufixo = referencia.split("|", 1)
    quebra = quebra_de(registro, chave)
    if sufixo == "bruto":
        if not quebra:
            return ""
        return json_compacto(quebra)
    return quebra.get(sufixo, "")


def json_compacto(obj):
    import json
    return json.dumps(obj, ensure_ascii=False, separators=(",", ":"))


def ausentes_em(registro, colunas=None):
    """Metricas esperadas que vieram sem valor — para a coluna metricas_ausentes."""
    falhas = []
    for campo, referencia in (colunas or COLUNAS_CSV):
        if not referencia or campo == "navegacoes_quebra":
            continue
        v = valor_coluna(registro, referencia)
        if v in ("", None):
