{"content": "#!/usr/bin/env python3
"""Junta as descricoes por folha (desc/folha_NN.json) numa tabela unica por
media_id, usando capas2_manifest.json como mapa idx -> pk.

Saida: _descricoes_stories.json
  {"<media_id>": {"descricao":..., "texto_sobreposto":..., "natureza":...,
                  "folha":"folha_01", "idx":1}}

Regra: se a folha nao existe ou o idx falta, o registro NAO entra como vazio —
fica contado no relatorio final para nao parecer que a descricao foi feita.
"""
import json
import os
import re

BASE = os.path.dirname(os.path.abspath(__file__))
DESC = os.path.join(BASE, "desc")
MANIF = os.path.join(BASE, "capas2_manifest.json")
SAIDA = os.path.join(BASE, "_descricoes_stories.json")


def carregar_manifesto():
    with open(MANIF, encoding="utf-8") as f:
        m = json.load(f)
    if isinstance(m, dict):
        m = m.get("itens") or m.get("registros") or m.get("capas") or list(m.values())
    mapa = {}
    for it in m:
        idx = it.get("idx") if isinstance(it, dict) else None
        pk = None
        if isinstance(it, dict):
            pk = it.get("pk") or it.get("media_id")
        if idx is None or pk is None:
            continue
        mapa[int(idx)] = {"pk": str(pk), "dia": it.get("dia") or it.get("data_brt"), "tipo": it.get("tipo")}
    return mapa


def itens_da_folha(caminho):
    with open(caminho, encoding="utf-8") as f:
        d = json.load(f)
    itens = d.get("itens") or {}
    nome = d.get("folha") or os.path.basename(caminho).replace(".json", "")
    saida = {}
    for k, v in itens.items():
        try:
            idx = int(re.sub(r"\D", "", str(k)) or 0)
        except ValueError:
            continue
        if not idx:
            continue
        if not isinstance(v, dict):
            continue
        saida[idx] = {
            "descricao": (v.get("descricao") or "").strip(),
            "texto_sobreposto": (v.get("texto_sobreposto") or v.get("texto") or "").strip(),
            "natureza": (v.get("natureza") or "").strip(),
            "folha": nome,
            "idx": idx,
        }
    return saida


def main():
    mapa = carregar_manifesto()
    print(f"manifesto: {len(mapa)} capas numeradas")

    folhas = sorted(
        os.path.join(DESC, a) for a in os.listdir(DESC) if re.fullmatch(r"folha_\d+\.json", a)
    ) if os.path.isdir(DESC) else []
    print(f"folhas de descricao encontradas: {len(folhas)}")

    por_idx = {}
    for caminho in folhas:
        try:
            por_idx.update(itens_da_folha(caminho))
        except Exception as e:  # folha corrompida nao pode derrubar o merge
            print(f"  AVISO: {os.path.basename(caminho)} ilegivel: {e}")

    final = {}
    sem_descricao = []
    for idx, info in sorted(mapa.items()):
        item = por_idx.get(idx)
        if not item or not item.get("descricao"):
            sem_descricao.append(idx)
            continue
        final[info["pk"]] = item

    with open(SAIDA, "w", encoding="utf-8") as f:
        json.dump(final, f, ensure_ascii=False, indent=1)

    print(f"descricoes aproveitadas: {len(final)}/{len(mapa)}")
    print(f"sem descricao: {len(sem_descricao)} -> {sem_descricao[:20]}")
    print(f"saida: {os.path.basename(SAIDA)}")


if __name__ == "__main__":
    main()
