{"content": "#!/usr/bin/env python3
"""Cruza a 'natureza' classificada por visao com o TIPO DE MIDIA real da captura
(1 = imagem, 2 = video). A tarja da folha pode ser mal lida; o dado da captura
nao. Reporta so as divergencias.

Uso: python conferir_natureza.py
"""
import json
import os
import glob

AQUI = os.path.dirname(os.path.abspath(__file__))
DESC = os.path.join(AQUI, "desc")
MANIF = os.path.join(AQUI, "capas2_manifest.json")
MIDIAS = os.path.join(AQUI, "run-2026-09", "midias_2026-09.json")


def carregar_manifesto():
    """idx -> media_id (aceita dict {idx: pk} ou {idx: {...}})"""
    d = json.load(open(MANIF, encoding="utf-8"))
    saida = {}
    for k, v in d.items():
        idx = int(str(k).lstrip("0") or 0)
        if isinstance(v, dict):
            pk = v.get("pk") or v.get("media_id") or v.get("id")
        else:
            pk = v
        if pk:
            saida[idx] = str(pk)
    return saida


def carregar_midias():
    """media_id -> tipo (1 imagem, 2 video)"""
    d = json.load(open(MIDIAS, encoding="utf-8"))
    itens = d.values() if isinstance(d, dict) else d
    if isinstance(d, dict) and "por_midia" in d:
        itens = d["por_midia"].values()
    saida = {}
    for m in itens:
        if not isinstance(m, dict):
            continue
        pk = m.get("pk") or m.get("media_id") or m.get("id")
        tipo = m.get("tipo") or m.get("media_type") or m.get("tipo_midia")
        if pk is None or tipo is None:
            continue
        try:
            tipo = int(tipo)
        except (TypeError, ValueError):
            continue
        saida[str(pk)] = tipo
    return saida


def main():
    manifesto = carregar_manifesto()
    tipos = carregar_midias()
    print(f"manifesto: {len(manifesto)} idx | tipos disponiveis: {len(tipos)}")

    div = []
    checados = 0
    sem_tipo = 0
    folhas = sorted(glob.glob(os.path.join(DESC, "folha_*.json")))
    for caminho in folhas:
        d = json.load(open(caminho, encoding="utf-8"))
        nome = d.get("folha") or os.path.splitext(os.path.basename(caminho))[0]
        for chave, item in (d.get("itens") or {}).items():
            idx = int(chave)
            nat = (item.get("natureza") or "").strip().lower()
            mid = manifesto.get(idx)
            if not mid or mid not in tipos:
                sem_tipo += 1
                continue
            checados += 1
            eh_video = tipos[mid] == 2
            if eh_video and nat != "video":
                div.append((nome, idx, tipos[mid], nat, "captura diz video"))
            elif not eh_video and nat == "video":
                div.append((nome, idx, tipos[mid], nat, "captura diz imagem"))
    print(f"itens cruzados: {checados} | sem tipo na captura: {sem_tipo}")
    if not div:
        print("nenhuma divergencia entre natureza e tipo de midia")
    else:
        print(f"divergencias: {len(div)}")
        for nome, idx, tipo, nat, motivo in div:
            print(f"  {nome} idx {idx}: tipo={tipo} natureza={nat} -> {motivo}")


if __name__ == "__main__":
    main()
