{"content": """"Fonte unica da verdade para CONTAGEM de publicacoes do feed do Instagram da ACIRV.

Regra central (aprendida na marra): a contagem de um periodo e o CONJUNTO de
shortcodes da varredura do grid do perfil, nunca o total de um export.
Todo o resto e conferido por SUBCONJUNTO contra essa referencia; qualquer item
de fora vira DIVERGENCIA e reprova a auditoria.

Nunca comparar por media_id entre fontes: o export oficial ora vem sem media_id,
ora usa outro espaco de id. A chave universal e o shortcode (11 chars).
Nunca confiar na data rotulada: a data verdadeira sai da decodificacao do
shortcode (validada 204/204 contra o grid). Export ja apareceu com 4 posts de
31/07 rotulados como agosto.

Uso:
    python publicacoes_feed.py auditar --periodo 2026-09 [--periodo 2026-08] [--json]
    python publicacoes_feed.py autoteste        # bateria negativa: prova que o auditor reprova
"""
import csv
import datetime
import json
import os
import sys

AQUI = os.path.dirname(os.path.abspath(__file__))
COFRE = os.path.abspath(os.path.join(AQUI, "..", "..", ".."))
ALFA = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789-_"
EPOCH_MS = 1314220021721
OFFSET_S = -10800  # BRT
MESES = {"2026-06": "junho", "2026-07": "julho", "2026-08": "agosto", "2026-09": "setembro", "2026-10": "outubro"}

# ---------------------------------------------------------------- id <-> data
def sc2mid(sc):
    n = 0
    for c in str(sc)[:11]:
        n = n * 64 + ALFA.index(c)
    return n

def mid2sc(mid):
    mid = int(mid)
    s = ""
    while mid > 0:
        s = ALFA[mid % 64] + s
        mid //= 64
    return s

def sc_para_data(sc):
    ms = (sc2mid(sc) >> 23) + EPOCH_MS
    return datetime.datetime.utcfromtimestamp(ms / 1000.0 + OFFSET_S)

def mes_de(sc):
    return sc_para_data(sc).strftime("%Y-%m")

# ------------------------------------------------------------------- fontes
def fonte_grid(caminho):
    """Varredura do grid do perfil: fotografia do que esta no feed. Fonte de referencia."""
    doc = json.load(open(caminho, encoding="utf-8"))
    itens = doc["itens"] if isinstance(doc, dict) else doc
    out = {}
    for x in itens:
        sc = str(x.get("sc") or x.get("shortcode"))[:11]
        out[sc] = {"rotulo": str(x.get("publicado_brt") or "")[:16], "dono": x.get("dono_grid"), "tipo": x.get("tipo_grid")}
    return out

def fonte_captura_jsonl(caminho):
    out = {}
    for linha in open(caminho, encoding="utf-8"):
        if linha.strip():
            x = json.loads(linha)
            sc = str(x.get("shortcode"))[:11]
            out[sc] = {"rotulo": str(x.get("publicado_brt") or "")[:16], "dono": x.get("vinculo"), "tipo": x.get("tipo_midia")}
    return out

def fonte_brutos(pasta):
    """Um JSON por post (captura crua com insights)."""
    out = {}
    for nome in os.listdir(pasta):
        if not nome.endswith(".json"):
            continue
        try:
            x = json.load(open(os.path.join(pasta, nome), encoding="utf-8"))
        except Exception:
            continue
        sc = str(x.get("shortcode") or nome[:-5])[:11]
        rot = "%s %s" % (x.get("data_publicacao") or "", x.get("hora_publicacao") or "")
        out[sc] = {"rotulo": rot.strip(), "dono": x.get("autor"), "tipo": x.get("tipo_midia")}
    return out

def fonte_base_csv(caminho, periodo=None):
    out = {}
    for r in csv.DictReader(open(caminho, encoding="utf-8"), delimiter=";"):
        if not r.get("shortcode"):
            continue
        sc = str(r["shortcode"])[:11]
        dt = "%s %s" % (r.get("data_publicacao") or "", r.get("hora_publicacao") or "")
        out[sc] = {"rotulo": dt.strip(), "dono": r.get("vinculo"), "tipo": r.get("tipo_midia")}
    return out

def fonte_export_xlsx(caminho):
    """Export oficial (Meta/planilha). Pode vir sem media_id e com data errada."""
    import openpyxl
    wb = openpyxl.load_workbook(caminho, data_only=True)
    ws = None
    for nome in ("Posts", "posts", "Sheet1"):
        if nome in wb.sheetnames:
            ws = wb[nome]
            break
    if ws is None:
        ws = wb.worksheets[0]
    cols = [c.value for c in ws[1]]
    out = {}
    for row in ws.iter_rows(min_row=2, values_only=True):
        r = dict(zip(cols, row))
        sc = r.get("shortcode")
        if not sc:
            continue
        sc = str(sc)[:11]
        out[sc] = {"rotulo": str(r.get("data_publicacao") or ""), "dono": r.get("vinculo"), "tipo": r.get("tipo_midia")}
    return out

def registro_fontes():
    """Registro declarativo: o que existe hoje e como ler cada coisa."""
    c = os.path.join(COFRE, "Hermes", "instagram-insights", "captura")
    r = os.path.join(COFRE, "000-Arquivos-originais", "Dados para mega-relatório pós Sudoexpo", "Redes sociais")
    b = os.path.join(COFRE, "85-Bases-e-Consultas")
    return {
        "grid": (fonte_grid, os.path.join(c, "setembro-2026", "_grid_inventario2.json"), "varredura do feed (02/10/2026)"),
        "captura_set": (fonte_captura_jsonl, os.path.join(c, "setembro-2026", "_setembro_2026_116.jsonl"), "captura post-a-post de setembro"),
        "brutos_ago": (fonte_brutos, os.path.join(c, "agosto-2026"), "brutos post-a-post de agosto"),
        "base_set": (lambda p: fonte_base_csv(p), os.path.join(b, "Instagram-Publicacoes-2026-09.csv"), "base canonica de setembro"),
        "base_08_09": (lambda p: fonte_base_csv(p), os.path.join(b, "Instagram-Publicacoes-2026-08-09.csv"), "base antiga 08+09 parcial"),
        "export_set": (fonte_export_xlsx, os.path.join(r, "instagram_acirvoficial_insights_setembro_2026.xlsx"), "export oficial setembro (01-14/09)"),
        "export_ago": (fonte_export_xlsx, os.path.join(r, "instagram_acirvoficial_insights_agosto_2026_MASTER(1).xlsx"), "export oficial agosto (MASTER)"),
        "grid_v1": (fonte_grid, os.path.join(c, "setembro-2026", "_grid_inventario.json"), "varredura antiga (parcial)"),
        "grid_v2": (fonte_grid, os.path.join(c, "setembro-2026", "_grid_inventario_v2.json"), "varredura antiga (parcial)"),
    }

# ----------------------------------------------------------------- auditoria
def auditar(periodo, fontes=None, referencia="grid"):
    fontes = fontes or registro_fontes()
    dados = {}
    for nome, (leitor, caminho, desc) in fontes.items():
        if not os.path.exists(caminho):
            dados[nome] = {"desc": desc, "erro": "nao encontrado"}
            continue
        dados[nome] = {"desc": desc, "itens": leitor(caminho)}

    ref = dados[referencia]["itens"]
    ref_periodo = {sc for sc in ref if mes_de(sc) == periodo}

    res = {"periodo": periodo, "referencia": referencia, "total_referencia": len(ref_periodo), "fontes": {}, "divergencias": [], "avisos": []}

    for nome, d in dados.items():
        if "itens" not in d:
            res["fontes"][nome] = {"desc": d["desc"], "erro": d["erro"]}
            continue
        itens = d["itens"]
        no_periodo = {sc for sc in itens if mes_de(sc) == periodo}
        fora = sorted(no_periodo - ref_periodo)
        faltando = sorted(ref_periodo - no_periodo) if nome.startswith("base") else []
        rotulos_errados = sorted(sc for sc in itens if d["itens"][sc].get("rotulo") and _mes_rotulo(d["itens"][sc]["rotulo"]) and _mes_rotulo(d["itens"][sc]["rotulo"]) != mes_de(sc))
        res["fontes"][nome] = {"desc": d["desc"], "total": len(itens), "no_periodo": len(no_periodo),
                               "fora_da_referencia": fora, "faltando_no_periodo": faltando, "rotulo_errado": rotulos_errados}
        if no_periodo and fora:
            res["divergencias"].append("%s traz %d post(s) que a varredura do feed nao tem: %s" % (nome, len(fora), ",".join(fora)))
        if faltando:
            res["divergencias"].append("%s esta sem %d post(s) do periodo: %s" % (nome, len(faltando), ",".join(faltando)))
        if rotulos_errados:
            res["avisos"].append("%s tem %d data(s) rotulada(s) errada(s) (a data do shortcode manda): %s" % (nome, len(rotulos_errados), ",".join(rotulos_errados)))

    res["veredito"] = "COMPLETO" if not res["divergencias"] else "REPROVADO"
    return res

def _mes_rotulo(txt):
    txt = str(txt).strip()[:7]
    return txt if len(txt) == 7 and txt[4] == "-" and txt[:4].isdigit() else None

def relatorio_md(res):
    L = []
    L.append("# Auditoria de publicações — %s" % (MESES.get(res["periodo"], res["periodo"])))
    L.append("")
    L.append("Veredito: **%s**" % res["veredito"])
    L.append("")
    L.append("Contagem do período = **%d posts**, definida pelo conjunto de shortcodes da %s." % (res["total_referencia"], res["referencia"]))
    L.append("")
    L.append("| Fonte | O que é | Itens | No período | Fora da referência | Rótulo de data errado |")
    L.append("|---|---|---|---|---|---|")
    for nome, f in res["fontes"].items():
        if "erro" in f:
            L.append("| `%s` | %s | — | — | %s | — |" % (nome, f["desc"], f["erro"]))
            continue
        L.append("| `%s` | %s | %d | %d | %d | %d |" % (nome, f["desc"], f["total"], f["no_periodo"], len(f["fora_da_referencia"]), len(f["rotulo_errado"])))
    L.append("")
    if res["divergencias"]:
        L.append("## Divergências")
        for d in res["divergencias"]:
            L.append("- %s" % d)
        L.append("")
    if res["avisos"]:
        L.append("## Avisos")
        for a in res["avisos"]:
            L.append("- %s" % a)
        L.append("")
    L.append("_Gerado por `Hermes/instagram-insights/ferramentas/publicacoes_feed.py`._")
    return "\n".join(L) + "\n"

def autoteste():
    """Bateria negativa: prova que a auditoria reprova quando deveria."""
    import tempfile
    base = registro_fontes()
    ok, falhas = 0, []

    def caso(nome, fonte, esperado_reprovar):
        global ok
        r = auditar("2026-09", fontes=fonte)
        reprovou = r["veredito"] != "COMPLETO"
        if reprovou == esperado_reprovar:
            ok += 1
        else:
            falhas.append("%s (veredito=%s, esperava reprovar=%s)" % (nome, r["veredito"], esperado_reprovar))

    # 1. dados reais: tem que passar
    caso("dados reais", base, False)

    # 2. post fantasma: alguem afirma um post que o feed nao tem
    f = {"grid": base["grid"], "base_set": base["base_set"], "invasor": (lambda p: {"ZZZfantasma1": {"rotulo": "2026-09-10", "dono": "x", "tipo": "p"}}, None, "fonte inventada")}
    caso("post fantasma", f, True)
    return ok, falhas

def main(argv):
    if len(argv) > 1 and argv[1] == "autoteste":
        ok, falhas = autoteste()
        print("autoteste: %d caso(s) ok, %d falha(s)" % (ok, len(falhas)))
        for x in falhas:
            print("   FALHA:", x)
        return 0 if not falhas else 1
    periodos = [argv[i + 1] for i, a in enumerate(argv) if a == "--periodo"]
    if not periodos:
        periodos = ["2026-09", "2026-08"]
    destino = os.path.join(COFRE, "Hermes", "instagram-insights", "auditorias")
    os.makedirs(destino, exist_ok=True)
    pior = 0
    for p in periodos:
        res = auditar(p)
        json.dump(res, open(os.path.join(destino, "AUDITORIA-%s.json" % p), "w", encoding="utf-8"), ensure_ascii=False, indent=2)
        open(os.path.join(destino, "AUDITORIA-%s.md" % p), "w", encoding="utf-8").write(relatorio_md(res))
        print("== %s: %s | %d posts na referencia" % (p, res["veredito"], res["total_referencia"]))
        for n, f in res["fontes"].items():
            if "erro" in f:
                print("   %-12s --  %s" % (n, f["erro"]))
            else:
                print("   %-12s itens=%-5d no periodo=%-5d fora=%d rotulo_errado=%d" % (n, f["total"], f["no_periodo"], len(f["fora_da_referencia"]), len(f["rotulo_errado"])))
        for d in res["divergencias"]:
            print("   ! %s" % d)
        for a in res["avisos"]:
            print("   ~ %s" % a)
        pior = 1 if res["veredito"] != "COMPLETO" else pior
    print("relatorios em Hermes/instagram-insights/auditorias/")
    return pior

if __name__ == "__main__":
    sys.exit(main(sys.argv))
