{"success": true, "name": "instagram-post-metrics-reporting", "file": "scripts/sink_save.py", "content": "#!/usr/bin/env python3
"""sink_save.py - TRANSFERENCIA PADRAO de payload do navegador para o disco.

POR QUE ESTE E O PADRAO
-----------------------
No app Electron, `a.download = ...; a.click()` abre um dialogo NATIVO de "Salvar"
que o agente nao consegue clicar: o arquivo nunca chega ao disco e o erro e silencioso
(nenhum .tmp aparece na pasta Downloads, nenhum erro no console). Por isso **nao use
download de blob nem Base64 colado no chat** para payload grande.

O canal que funciona: o navegador NAVEGA para este sink local.
O CSP do Instagram restringe `connect-src` (fetch/XHR/beacon) e `frame-src` (iframe),
mas NAO restringe navegacao de topo -- entao `location.href = 'http://127.0.0.1:PORT/salvar?...'`
entrega o arquivo. window.open costuma ser bloqueado (popup) e cai no mesmo comportamento:
navega a aba atual.

USO (padrao da skill, sempre nesta ordem)
-----------------------------------------
1. Suba o sink ANTES de coletar, apontando para a pasta da rodada:

       python sink_save.py 8766 "<pasta-da-rodada>"

   Confirme com `curl -s http://127.0.0.1:8766/health` (o agente NAO consegue sondar
   do navegador: fetch para 127.0.0.1 e bloqueado pelo connect-src do CSP).

2. No console da pagina, ao terminar a coleta, entregue a rodada INTEIRA numa unica
   navegacao (rota /salvar_lote):

       __IG.entregarLote()      // manda day_shells + midias + insights de uma vez

   Ou, arquivo por arquivo (rota /salvar, uma navegacao cada):

       __IG.entregar('insights_2026-09.json', payload)

   O helper __IG (de coletar_stories_periodo.js) ja aplica gzip + base64 +
   encodeURIComponent e guarda uma copia do base64 em localStorage antes de navegar.

3. Confirme no disco. O sink valida JSON e devolve `bytes` + `sha256` por arquivo;
   compare com o que o console reportou ANTES de navegar.

4. Depois da navegacao a aba fica no sink: volte com `browser_navigate` para
   https://www.instagram.com/... (o estado JS da pagina se perde — por isso o passo 3).
   Se algo falhou, o base64 continua em localStorage: reabra o Instagram, cole o
   coletor de novo e rode `__IG.recuperar('nome.json')`.

REGRAS
------
- `nome` e sempre reduzido a basename: o sink nunca escreve fora da pasta de destino.
- Aceita base64 puro ou base64 de gzip (detectado pelo magic 1f 8b).
- Se o arquivo terminar em .json, o JSON e validado antes de gravar (falha = nada gravado).
- Porta padrao 8766. Se ja houver um sink rodando nela, reaproveite-o.
"""
import base64
import gzip
import hashlib
import json
import os
import sys
import urllib.parse
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer

DESTINO = os.path.abspath(sys.argv[2] if len(sys.argv) > 2 else ".")
PORTA_PADRAO = 8766


def decodificar(dado):
    """base64 -> bytes, desfazendo gzip quando presente."""
    try:
        bruto = base64.b64decode(dado, validate=False)
    except Exception as e:
        raise ValueError(f"base64 invalido: {e}") from e
    if bruto[:2] == b"\x1f\x8b":
        try:
            bruto = gzip.decompress(bruto)
        except Exception as e:
            raise ValueError(f"gzip corrompido: {e}") from e
    return bruto


def gravar(nome, bruto):
    """Grava com validacao de JSON e devolve o recibo."""
    nome = os.path.basename(nome)
    if nome.endswith(".json"):
        try:
            json.loads(bruto.decode("utf-8"))
        except Exception as e:
            raise ValueError(f"json invalido em {nome}: {e}") from e
    os.makedirs(DESTINO, exist_ok=True)
    caminho = os.path.join(DESTINO, nome)
    with open(caminho, "wb") as fh:
        fh.write(bruto)
    return {"arquivo": caminho, "bytes": len(bruto), "sha256": hashlib.sha256(bruto).hexdigest()}


class Handler(BaseHTTPRequestHandler):
    protocol_version = "HTTP/1.1"
    max_line = 16 * 1024 * 1024  # o payload grande viaja na query string

    def log_message(self, fmt, *a):
        pass

    def _responder(self, code, obj):
        corpo = json.dumps(obj, ensure_ascii=False).encode("utf-8")
        self.send_response(code)
        self.send_header("Content-Type", "application/json; charset=utf-8")
        self.send_header("Access-Control-Allow-Origin", "*")
        self.send_header("Content-Length", str(len(corpo)))
        self.end_headers()
        self.wfile.write(corpo)

    def do_GET(self):
        u = urllib.parse.urlparse(self.path)
        q = urllib.parse.parse_qs(u.query, max_num_fields=10)

        if u.path == "/health":
            return self._responder(200, {"ok": True, "ping": "ping-ok", "destino": DESTINO})

        if u.path == "/salvar":
            nome = os.path.basename((q.get("nome") or [""])[0])
            dado = (q.get("d") or [""])[0]
            if not nome or not dado:
                return self._responder(400, {"erro": "informe nome= e d="})
            try:
                recibo = gravar(nome, decodificar(dado))
            except ValueError as e:
                return self._responder(400, {"erro": str(e)})
            return self._responder(200, {"ok": True, **recibo})

        if u.path == "/salvar_lote":
            # UMA navegacao entrega a rodada inteira:
            # d = base64(gzip(JSON.stringify({arquivos:[{nome, texto}]})))
            dado = (q.get("d") or [""])[0]
            if not dado:
                return self._responder(400, {"erro": "informe d="})
            try:
                doc = json.loads(decodificar(dado).decode("utf-8"))
            except Exception as e:
                return self._responder(400, {"erro": f"lote ilegivel: {e}"})
            arquivos = doc.get("arquivos") or []
            if not arquivos:
                return self._responder(400, {"erro": "lote sem arquivos"})
            escritos, erros = [], []
            for item in arquivos:
                try:
                    recibo = gravar(item["nome"], str(item["texto"]).encode("utf-8"))
                    escritos.append({"nome": os.path.basename(item["nome"]), **recibo})
                except Exception as e:
                    erros.append({"nome": item.get("nome"), "erro": str(e)})
            return self._responder(200 if not erros else 207,
                                   {"ok": not erros, "escritos": escritos, "erros": erros})

        return self._responder(404, {"erro": "rota desconhecida",
                                     "rotas": ["/health", "/salvar", "/salvar_lote"]})


if __name__ == "__main__":
    porta = int(sys.argv[1]) if len(sys.argv) > 1 else PORTA_PADRAO
    print(f"sink_save: http://127.0.0.1:{porta} -> {DESTINO}", flush=True)
    ThreadingHTTPServer(("127.0.0.1", porta), Handler).serve_forever()
